package vn.svframe.svframelib.api.crafting.uifilters;
import vn.svframe.svframelib.api.util.ui.FriendlyFeedbackProvider; import net.minecraft.item.*; import net.minecraft.registry.Registries; import net.minecraft.util.Identifier;
public class VanillaUIFilter implements UIFilter { public String getIdentifier(){return "vanilla";} public boolean matches(ItemStack stack,String argument,String data,FriendlyFeedbackProvider f){if(stack==null||stack.isEmpty())return false;Identifier id=Registries.ITEM.getId(stack.getItem());String arg=argument==null?"":argument.trim().toLowerCase();return id.toString().equals(arg)||id.getPath().equals(arg);} public boolean isValid(String argument,String data,FriendlyFeedbackProvider f){return Identifier.tryParse(argument)!=null;} public boolean fullyDefinesItem(){return true;} public ItemStack getItemStack(String argument,String data,FriendlyFeedbackProvider f){Identifier id=Identifier.tryParse(argument);if(id==null)return ItemStack.EMPTY;Item item=Registries.ITEM.get(id);return item==Items.AIR?ItemStack.EMPTY:new ItemStack(item);} public String exampleArgument(){return "minecraft:diamond";} }
